/**
 * Golden two-mode baseline candidate (specs/02 §2–7, Gate 1).
 *
 * Namespace form only (`name` / `inject` / `Config` / `apply`, no default
 * export): the Cordis Loader normalizes modules through
 * `exports.default ?? exports`, so a stray default export would drop these
 * sibling exports (pinned DSH postmortem 0001). All behavior goes through the
 * candidate SDK so the surface stays typed, namespaced and effect-owned.
 *
 * @module @dsh-evolve-le/candidate-baseline
 */

import type { Context } from '@deepseek-ai/cordis'
import Schema from '@deepseek-ai/schemastery'
import { defineCandidate } from '@dsh-evolve-le/candidate-sdk'

/** Cordis plugin name; also the Loader runtime display name. */
export const name = 'self-evolving-candidate'

/** The only service this candidate touches (specs/02 §5: systemPrompt). */
export const inject = ['systemPrompt']

/** Baseline candidate configuration validated by the Loader at mount. */
export interface Config {
  /** Canonical candidate identity assigned by the trusted builder. */
  candidateId: string
  /** Execution mode; bound to behavior by the candidate SDK. */
  mode: 'solve' | 'propose'
}

export const Config: Schema<Config> = Schema.object({
  candidateId: Schema.string().required(),
  mode: Schema.union(['solve', 'propose']).default('solve'),
})

const candidate = defineCandidate<Config>({
  solve: {
    promptSection: (config) => ({
      name: 'candidate:identity',
      order: 100,
      text:
        `You are executing under self-evolving candidate ${config.candidateId} ` +
        'in solve mode. Before using a dataset, read its README and schema ' +
        'for the tokenizer and fields it mandates. Re-read the task output ' +
        'format before writing results, and verify any file you produce ' +
        'parses or opens before exiting.',
    }),
  },
  propose: {
    promptSection: (config) => ({
      name: 'candidate:proposal-policy',
      order: 100,
      text:
        `You are executing under self-evolving candidate ${config.candidateId} ` +
        'in propose mode. Produce one proposal manifest describing a minimal, ' +
        'testable change; do not modify runtime behavior in this mode.',
    }),
  },
})

/**
 * Activate the candidate's contribution for the configured mode. The section
 * is effect-owned, so disposing this plugin's Fiber removes it and nothing
 * else — which is exactly what the builder's unload-invariant stage asserts.
 * @param ctx - the plugin's Fiber context.
 * @param config - validated entry config from `cordis.yml`.
 */
export function apply(ctx: Context, config: Config): void {
  candidate.register(ctx, config)
}

files.tests/candidate.spec.ts:
/**
 * Candidate-owned spec for the golden baseline (specs/02 §7). These are the
 * mechanism/preservation assertions declared in candidate.json: mode wiring
 * and effect ownership, verified against the SDK testkit without a live
 * harness, network or model.
 */
import { describe, expect, it } from 'vitest'
import { createHarness } from '@dsh-evolve-le/candidate-sdk/testkit'
import { apply, type Config } from '../src/index.js'

const config = (mode: Config['mode']): Config => ({
  candidateId: 'c_gate1goldenfixture000000000000',
  mode,
})

describe('self-evolving-candidate baseline', () => {
  it('registers exactly one candidate:identity section in solve mode', () => {
    const harness = createHarness()
    apply(harness.ctx, config('solve'))
    const sections = harness.sections()
    expect(sections).toHaveLength(1)
    expect(sections[0]?.name).toBe('candidate:identity')
    expect(sections[0]?.order).toBe(100)
    expect(sections[0]?.text).toContain('c_gate1goldenfixture000000000000')
    expect(sections[0]?.text).toContain('solve mode')
    expect(sections[0]?.text).toContain('read its README and schema')
  })

  it('registers exactly one candidate:proposal-policy section in propose mode', () => {
    const harness = createHarness()
    apply(harness.ctx, config('propose'))
    const sections = harness.sections()
    expect(sections).toHaveLength(1)
    expect(sections[0]?.name).toBe('candidate:proposal-policy')
    expect(sections[0]?.text).toContain('propose mode')
  })

  it('owns its section through an effect: disposal removes it and runs teardown', () => {
    const harness = createHarness()
    apply(harness.ctx, config('solve'))
    expect(harness.effects()).toHaveLength(1)
    expect(harness.effects()[0]?.disposed).toBe(false)

    harness.dispose()
    expect(harness.sections()).toEqual([])
    expect(harness.effects()[0]?.disposed).toBe(true)
  })

  it('registers nothing beyond the single section', () => {
    const harness = createHarness()
    apply(harness.ctx, config('solve'))
    // The SDK surface records sections and effects only; a baseline candidate
    // contributes exactly one of each.
    expect(harness.sections()).toHaveLength(1)
    expect(harness.effects()).toHaveLength(1)
  })
})
